parameters.query:
with inbound as (
  select m.conversation_id, m.channel, m.at,
         (select min(o.at) from messages o where o.conversation_id = m.conversation_id and o.direction = 'out' and o.at >= m.at) as answered_at
  from messages m where m.direction = 'in' and m.at >= date_trunc('day', now())
)
select
  (select json_object_agg(channel, n) from (select channel, count(distinct conversation_id) n from inbound group by channel) x) as by_channel,
  (select round(percentile_cont(0.5) within group (order by extract(epoch from (answered_at - at)) / 60)::numeric, 1) from inbound where answered_at is not null) as median_minutes,
  (select count(*) from conversations where sla_due_at >= date_trunc('day', now()) and escalated) as missed_targets,
  (select count(*) from conversations where status = 'open' and assigned_to in ('Tolu', 'Bisi')) as open_handovers;

